sys_variable_value.value:
(function(outputs, steps, stepResult, assertEqual)
{
	var test = new x_snc_devtools.TestAPI(outputs, steps, stepResult, assertEqual);
	
	test.SetResult(true);

	function TestCase_SetAppRepo(vApp, strUrl, strBranch, strCredentialSysId, strMidServerSysid, vExpected)
	{
		function TestCase_SetAppRepo_CheckResult(vInput,vExpected,vResult)
		{
			if (vExpected != vResult)
			{
				return false;
			}
			if (vExpected == true)
			{
				var grApp = new GlideRecord('sys_app');
				grApp.addQuery('sys_id','=',GetAppRecord(vInput['vApp']).sys_id);
				grApp.addQuery('x_snc_devtools_repo_url','=',vInput['strUrl']);
				grApp.query();
				if (grApp.getRowCount() != 1)
				{
					test.Log('x_snc_devtools_repo_url incorrect!');
					return false;
				}		
				
				var grRepo = GetRepoConfigRecord(vApp);
				if (IsValidRecord(grRepo) == false)
				{
					test.Log('Could not load sys_repo_config record!');
					return false;
				}
				if (grRepo.url != strUrl)
				{
					test.Log('Unexpected url in sys_repo_config record!');
					return false;
				}
				if (GetStringValue(strBranch) != '')
				{
					if (grRepo.current_branch != strBranch)
					{
						test.Log('Unexpected current_branch in sys_repo_config record!');		
						return false;
					}
				}
				if (GetStringValue(strCredentialSysId) != '')
				{
					if (grRepo.credential != strCredentialSysId)
					{
						test.Log('Unexpected credential in sys_repo_config record!');
						return false;
					}
				}
				if (GetStringValue(strMidServerSysid) != '')
				{
					if (grRepo.mid_server != strMidServerSysid)
					{
						test.Log('Unexpected mid_server in sys_repo_config record!');
						return false;
					}
				}
				
				var grDependency = new GlideRecord('x_snc_devtools_dependency');
				grDependency.addQuery('dependency','=',GetAppRecord(vInput['vApp']).sys_id);
				grDependency.addQuery('repo_url','!=',vInput['strUrl']);
				grDependency.query();
				if (grDependency.getRowCount() != 0)
				{
					test.Log('Unexpected url in x_snc_devtools_dependency record!');
					return false;
				}					
			}
			return true;
		}

		test.TestCase(
			'Function SetAppRepo()',
			SetAppRepo,
			{
				'vApp': vApp,
				'strUrl': strUrl,
				'strBranch': strBranch,
				'strCredentialSysId': strCredentialSysId,
				'strMidServerSysid': strMidServerSysid
			},
			vExpected,
			TestCase_SetAppRepo_CheckResult);
	}

	TestCase_SetAppRepo(null,null,null,null,null,false);

	var strAppSysId = AppCreate('Test Alpha','scoped','x_test_alpha');
	TestCase_SetAppRepo(strAppSysId,'https://github.com/test/beta.git',null,null,null,false);

	var grRepoConfig = new GlideRecord('sys_repo_config');
	grRepoConfig.initialize();
	grRepoConfig.url = 'https://github.com/test/alpha.git'
	grRepoConfig.sys_app = strAppSysId;
	GlideRecordInsert(grRepoConfig);


	TestCase_SetAppRepo(strAppSysId,null,null,null,null,false);
	TestCase_SetAppRepo(strAppSysId,'not_a_valid_url',null,null,null,false);
	TestCase_SetAppRepo(strAppSysId,'https://github.com/test/beta.git',null,null,null,true);
	TestCase_SetAppRepo(strAppSysId,'https://github.com/test/alpha.git',null,null,null,true);
	TestCase_SetAppRepo(strAppSysId,'https://github.com/test/beta.git','dev',GetPseudoSysId(),GetPseudoSysId(),true);
		
	return test.GetResult();
	
})(outputs, steps, stepResult, assertEqual);
